--
-- Name: admin_demo_case_grants; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.admin_demo_case_grants (
    id bigint NOT NULL,
    grantee_kind text NOT NULL,
    grantee_user_id integer,
    grantee_organization_id bigint,
    case_id uuid NOT NULL,
    brand_id bigint NOT NULL,
    capability text DEFAULT 'demo.customer.preview'::text NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    valid_from timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    version bigint DEFAULT 1 NOT NULL,
    created_by_user_id integer NOT NULL,
    created_reason text NOT NULL,
    note text DEFAULT ''::text NOT NULL,
    request_payload_hash text NOT NULL,
    created_request_id text NOT NULL,
    revoked_by_user_id integer,
    revoked_reason text,
    revoked_request_id text,
    revoked_at timestamp with time zone,
    expired_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT admin_demo_case_grants_brand_id_check CHECK ((brand_id > 0)),
    CONSTRAINT admin_demo_case_grants_capability_check CHECK ((capability = 'demo.customer.preview'::text)),
    CONSTRAINT admin_demo_case_grants_created_reason_check CHECK (((char_length(btrim(created_reason)) >= 2) AND (char_length(btrim(created_reason)) <= 500))),
    CONSTRAINT admin_demo_case_grants_grantee_kind_check CHECK ((grantee_kind = ANY (ARRAY['user'::text, 'organization'::text]))),
    CONSTRAINT admin_demo_case_grants_grantee_shape_check CHECK ((((grantee_kind = 'user'::text) AND (grantee_user_id IS NOT NULL) AND (grantee_organization_id IS NULL)) OR ((grantee_kind = 'organization'::text) AND (grantee_user_id IS NULL) AND (grantee_organization_id IS NOT NULL)))),
    CONSTRAINT admin_demo_case_grants_note_check CHECK ((char_length(note) <= 500)),
    CONSTRAINT admin_demo_case_grants_request_payload_hash_check CHECK ((request_payload_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT admin_demo_case_grants_revocation_shape_check CHECK ((((status = 'active'::text) AND (revoked_at IS NULL) AND (expired_at IS NULL) AND (revoked_by_user_id IS NULL) AND (revoked_reason IS NULL)) OR ((status = 'revoked'::text) AND (revoked_at IS NOT NULL) AND (expired_at IS NULL) AND (revoked_by_user_id IS NOT NULL) AND ((char_length(btrim(revoked_reason)) >= 2) AND (char_length(btrim(revoked_reason)) <= 500))) OR ((status = 'expired'::text) AND (revoked_at IS NULL) AND (expired_at IS NOT NULL) AND (revoked_by_user_id IS NULL) AND (revoked_reason IS NULL)))),
    CONSTRAINT admin_demo_case_grants_status_check CHECK ((status = ANY (ARRAY['active'::text, 'revoked'::text, 'expired'::text]))),
    CONSTRAINT admin_demo_case_grants_version_check CHECK ((version >= 1)),
    CONSTRAINT admin_demo_case_grants_window_check CHECK ((expires_at > valid_from))
);


