--
-- Name: admin_provider_downgrade_plans; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.admin_provider_downgrade_plans (
    id bigint NOT NULL,
    provider_user_id integer NOT NULL,
    strategy text NOT NULL,
    target_provider_user_id integer,
    status text DEFAULT 'draft'::text NOT NULL,
    dependency_snapshot jsonb DEFAULT '{}'::jsonb NOT NULL,
    next_steps jsonb DEFAULT '[]'::jsonb NOT NULL,
    expected_identity_version bigint NOT NULL,
    version bigint DEFAULT 1 NOT NULL,
    created_by_user_id integer NOT NULL,
    created_reason text NOT NULL,
    created_request_id text NOT NULL,
    confirmed_by_user_id integer,
    confirmed_reason text,
    confirmed_request_id text,
    confirmed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT admin_provider_downgrade_plans_completion_shape_check CHECK (((status <> 'completed'::text) OR ((confirmed_by_user_id IS NOT NULL) AND (confirmed_at IS NOT NULL) AND ((char_length(btrim(confirmed_reason)) >= 2) AND (char_length(btrim(confirmed_reason)) <= 500))))),
    CONSTRAINT admin_provider_downgrade_plans_created_reason_check CHECK (((char_length(btrim(created_reason)) >= 2) AND (char_length(btrim(created_reason)) <= 500))),
    CONSTRAINT admin_provider_downgrade_plans_expected_identity_version_check CHECK ((expected_identity_version >= 1)),
    CONSTRAINT admin_provider_downgrade_plans_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'blocked'::text, 'ready'::text, 'completed'::text, 'cancelled'::text]))),
    CONSTRAINT admin_provider_downgrade_plans_strategy_check CHECK ((strategy = ANY (ARRAY['transfer_upstream'::text, 'platform_managed'::text, 'settle_then_downgrade'::text]))),
    CONSTRAINT admin_provider_downgrade_plans_target_check CHECK ((((strategy = 'transfer_upstream'::text) AND (target_provider_user_id IS NOT NULL) AND (target_provider_user_id <> provider_user_id)) OR ((strategy = ANY (ARRAY['platform_managed'::text, 'settle_then_downgrade'::text])) AND (target_provider_user_id IS NULL)))),
    CONSTRAINT admin_provider_downgrade_plans_version_check CHECK ((version >= 1))
);


