-- Name: agent_sku_overrides; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.agent_sku_overrides (
    id integer NOT NULL,
    agent_user_id integer NOT NULL,
    sku_template_id integer,
    custom_name text NOT NULL,
    custom_subtitle text,
    custom_sales_pitch text,
    retail_cents integer NOT NULL,
    is_active boolean DEFAULT true,
    margin_warning text,
    admin_approved_at timestamp without time zone,
    admin_approved_by integer,
    created_at timestamp without time zone DEFAULT now(),
    updated_at timestamp without time zone DEFAULT now(),
    sort_order integer DEFAULT 0 NOT NULL,
    custom_scene text,
    deleted_at timestamp with time zone,
    retail_sku_id text NOT NULL,
    points_granted bigint NOT NULL,
    source_template_id integer,
    version integer DEFAULT 1 NOT NULL,
    client_request_id text,
    CONSTRAINT chk_agent_retail_sku_client_request CHECK (((client_request_id IS NULL) OR ((char_length(btrim(client_request_id)) >= 8) AND (char_length(btrim(client_request_id)) <= 80)))),
    CONSTRAINT chk_agent_retail_sku_copy_lengths CHECK ((((custom_subtitle IS NULL) OR (char_length(custom_subtitle) <= 240)) AND ((custom_sales_pitch IS NULL) OR (char_length(custom_sales_pitch) <= 1000)) AND ((custom_scene IS NULL) OR (char_length(custom_scene) <= 500)))),
    CONSTRAINT chk_agent_retail_sku_identity CHECK ((retail_sku_id ~ '^RSKU-[A-Z0-9-]{8,59}$'::text)),
    CONSTRAINT chk_agent_retail_sku_money CHECK (((retail_cents > 0) AND (retail_cents <= 2000000000))),
    CONSTRAINT chk_agent_retail_sku_name CHECK (((char_length(btrim(custom_name)) >= 1) AND (char_length(btrim(custom_name)) <= 120))),
    CONSTRAINT chk_agent_retail_sku_points CHECK (((points_granted > 0) AND (points_granted <= '9000000000000000'::bigint))),
    CONSTRAINT chk_agent_retail_sku_tombstone CHECK (((deleted_at IS NULL) OR (is_active = false))),
    CONSTRAINT chk_agent_retail_sku_version CHECK ((version >= 1))
);


