-- Name: billing_debt_offset_outbox; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.billing_debt_offset_outbox (
    event_key text NOT NULL,
    user_id integer NOT NULL,
    feature_code text NOT NULL,
    charge_tx_id bigint NOT NULL,
    ledger_type text NOT NULL,
    consumed_points bigint NOT NULL,
    idempotency_key text,
    status text DEFAULT 'pending'::text NOT NULL,
    retry_count smallint DEFAULT 0 NOT NULL,
    next_retry_at timestamp with time zone DEFAULT now() NOT NULL,
    last_error text,
    result_jsonb jsonb,
    refunded_points bigint DEFAULT 0 NOT NULL,
    reversed_points bigint DEFAULT 0 NOT NULL,
    reversal_jsonb jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    completed_at timestamp with time zone,
    cancelled_at timestamp with time zone,
    reversed_at timestamp with time zone,
    CONSTRAINT billing_debt_offset_outbox_event_identity_check CHECK ((event_key = ((('billing_debt_offset:'::text || ledger_type) || ':'::text) || (charge_tx_id)::text))),
    CONSTRAINT billing_debt_offset_outbox_ledger_check CHECK ((ledger_type = ANY (ARRAY['legacy'::text, 'v35'::text]))),
    CONSTRAINT billing_debt_offset_outbox_points_check CHECK ((consumed_points > 0)),
    CONSTRAINT billing_debt_offset_outbox_refund_points_check CHECK (((refunded_points >= 0) AND (refunded_points <= consumed_points) AND (reversed_points >= 0) AND (reversed_points <= consumed_points))),
    CONSTRAINT billing_debt_offset_outbox_retry_check CHECK ((retry_count >= 0)),
    CONSTRAINT billing_debt_offset_outbox_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'completed'::text, 'manual'::text, 'cancelled'::text, 'reversed'::text]))),
    CONSTRAINT billing_debt_offset_outbox_terminal_check CHECK ((((status <> 'completed'::text) OR ((result_jsonb IS NOT NULL) AND (completed_at IS NOT NULL))) AND ((status <> 'manual'::text) OR (last_error IS NOT NULL)) AND ((status <> 'cancelled'::text) OR ((cancelled_at IS NOT NULL) AND (refunded_points = consumed_points))) AND ((status <> 'reversed'::text) OR ((result_jsonb IS NOT NULL) AND (completed_at IS NOT NULL) AND (reversal_jsonb IS NOT NULL) AND (reversed_at IS NOT NULL) AND (refunded_points = consumed_points) AND (reversed_points = COALESCE(((result_jsonb ->> 'offset_points'::text))::bigint, (0)::bigint))))))
);


