    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    completed_at timestamp with time zone,
    refund_pending_at timestamp with time zone,
    refunded_at timestamp with time zone,
    CONSTRAINT billing_deduction_idempotency_deducted_check CHECK (((deducted IS NULL) OR (deducted >= 0))),
    CONSTRAINT billing_deduction_idempotency_fingerprint_check CHECK ((request_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT billing_deduction_idempotency_ledger_check CHECK (((ledger_type IS NULL) OR (ledger_type = ANY (ARRAY['legacy'::text, 'v35'::text])))),
    CONSTRAINT billing_deduction_idempotency_refund_timestamp_check CHECK ((((status <> 'refund_pending'::text) OR (refund_pending_at IS NOT NULL)) AND ((status <> 'refunded'::text) OR (refunded_at IS NOT NULL)))),
    CONSTRAINT billing_deduction_idempotency_status_check CHECK ((status = ANY (ARRAY['in_progress'::text, 'charged'::text, 'refund_pending'::text, 'refunded'::text]))),
    CONSTRAINT billing_deduction_idempotency_terminal_identity_check CHECK (((status = 'in_progress'::text) OR ((response_jsonb IS NOT NULL) AND (charge_tx_id IS NOT NULL) AND (ledger_type = ANY (ARRAY['legacy'::text, 'v35'::text])) AND (deducted > 0) AND (completed_at IS NOT NULL)))),
    CONSTRAINT billing_deduction_idempotency_total_cost_check CHECK ((total_cost >= 0))
);


