    CONSTRAINT bonus_grants_pool_check CHECK ((pool = 'bonus'::text)),
    CONSTRAINT bonus_grants_status_check CHECK ((status = ANY (ARRAY['active'::text, 'expired_frozen'::text, 'renewed'::text, 'fully_consumed'::text])))
);


