    source_order_id text NOT NULL,
    policy_code text NOT NULL,
    digital_goods_acknowledged_at timestamp with time zone NOT NULL,
    status text DEFAULT 'requested'::text NOT NULL,
    reason text DEFAULT ''::text NOT NULL,
    execution_jsonb jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    reason_category text DEFAULT 'negotiated_other'::text NOT NULL,
    decision_kind text DEFAULT 'negotiated'::text NOT NULL,
    eligibility_jsonb jsonb DEFAULT '{}'::jsonb NOT NULL,
    reviewed_by_user_id integer,
    reviewed_at timestamp with time zone,
    approved_at timestamp with time zone,
    internal_settled_at timestamp with time zone,
    cash_status text DEFAULT 'not_started'::text NOT NULL,
