    revoked_paid_points bigint DEFAULT 0 NOT NULL,
    revoked_bonus_points bigint DEFAULT 0 NOT NULL,
    restored_inventory_points bigint DEFAULT 0 NOT NULL,
    revenue_reversed_cents bigint DEFAULT 0 NOT NULL,
    row_version bigint DEFAULT 1 NOT NULL,
    mandatory_evidence_status text DEFAULT 'not_applicable'::text NOT NULL,
    CONSTRAINT chk_consumer_refund_amounts CHECK (((refund_amount_cents >= 0) AND (revoked_paid_points >= 0) AND (revoked_bonus_points >= 0) AND (restored_inventory_points >= 0) AND (revenue_reversed_cents >= 0) AND (row_version >= 1))),
    CONSTRAINT chk_consumer_refund_cash_status CHECK ((cash_status = ANY (ARRAY['not_started'::text, 'queued'::text, 'provider_processing'::text, 'completed'::text, 'failed'::text, 'manual_review'::text]))),
    CONSTRAINT chk_consumer_refund_decision_kind CHECK ((decision_kind = ANY (ARRAY['mandatory'::text, 'negotiated'::text]))),
    CONSTRAINT chk_consumer_refund_eligibility_object CHECK ((jsonb_typeof(eligibility_jsonb) = 'object'::text)),
    CONSTRAINT chk_consumer_refund_execution CHECK ((jsonb_typeof(execution_jsonb) = 'object'::text)),
    CONSTRAINT chk_consumer_refund_mandatory_evidence CHECK ((mandatory_evidence_status = ANY (ARRAY['not_applicable'::text, 'claimed'::text, 'verified'::text, 'rejected'::text]))),
    CONSTRAINT chk_consumer_refund_parties CHECK ((consumer_user_id <> responsible_service_user_id)),
    CONSTRAINT chk_consumer_refund_policy CHECK ((btrim(policy_code) <> ''::text)),
    CONSTRAINT chk_consumer_refund_status CHECK ((status = ANY (ARRAY['requested'::text, 'service_review'::text, 'platform_execution'::text, 'completed'::text, 'rejected'::text, 'manual_review'::text])))
);


