    agent_payable_cents bigint,
    CONSTRAINT chk_dealer_consumer_sale_allocations CHECK (((jsonb_typeof(seller_lot_allocations) = 'array'::text) AND (jsonb_array_length(seller_lot_allocations) > 0))),
    CONSTRAINT chk_dealer_consumer_sale_collector CHECK ((payment_collector = 'PLATFORM'::text)),
    CONSTRAINT chk_dealer_consumer_sale_cost_positive CHECK ((seller_cost_basis_cents > 0)),
    CONSTRAINT chk_dealer_consumer_sale_markup CHECK ((downstream_markup_bps >= 10000)),
    CONSTRAINT chk_dealer_consumer_sale_money CHECK (((seller_cost_basis_cents >= 0) AND (sale_amount_cents > 0) AND (margin_cents >= 0) AND (sale_amount_cents = (seller_cost_basis_cents + margin_cents)))),
    CONSTRAINT chk_dealer_consumer_sale_paid_fields CHECK ((((state = ANY (ARRAY['reserved'::text, 'cancelled'::text])) AND (paid_at IS NULL) AND (transfer_id IS NULL) AND (revenue_ledger_id IS NULL)) OR ((state = ANY (ARRAY['paid'::text, 'refund_pending'::text, 'refunded'::text, 'manual_review'::text])) AND (paid_at IS NOT NULL) AND (transfer_id IS NOT NULL) AND (revenue_ledger_id IS NOT NULL)))),
    CONSTRAINT chk_dealer_consumer_sale_parties CHECK ((seller_user_id <> consumer_user_id)),
    CONSTRAINT chk_dealer_consumer_sale_payout_v2 CHECK ((((principal_recovery_cents IS NULL) AND (agent_payable_cents IS NULL)) OR ((principal_recovery_cents >= 0) AND (principal_recovery_cents <= seller_cost_basis_cents) AND (agent_payable_cents = (principal_recovery_cents + margin_cents)) AND (agent_payable_cents <= sale_amount_cents)))),
    CONSTRAINT chk_dealer_consumer_sale_points CHECK ((points > 0)),
    CONSTRAINT chk_dealer_consumer_sale_policy CHECK ((btrim(digital_goods_policy_code) <> ''::text)),
    CONSTRAINT chk_dealer_consumer_sale_refund_owner CHECK ((refund_responsible_user_id = seller_user_id)),
    CONSTRAINT chk_dealer_consumer_sale_state CHECK ((state = ANY (ARRAY['reserved'::text, 'paid'::text, 'refund_pending'::text, 'refunded'::text, 'manual_review'::text, 'cancelled'::text]))),
    CONSTRAINT chk_dealer_consumer_sale_version CHECK ((btrim(pricing_version) <> ''::text))
);


