    CONSTRAINT chk_dealer_lot_points_conservation CHECK (((remaining_points >= 0) AND (reserved_points >= 0) AND ((remaining_points + reserved_points) <= original_points))),
    CONSTRAINT chk_dealer_lot_points_positive CHECK ((original_points > 0)),
    CONSTRAINT chk_dealer_lot_pricing_version CHECK ((btrim(pricing_version) <> ''::text)),
    CONSTRAINT chk_dealer_lot_promotion_lineage_v2 CHECK ((((promotion_campaign_id IS NULL) AND (promotion_funding_scope IS NULL) AND (promotion_product_code IS NULL) AND (promotion_root_catalog_version IS NULL)) OR ((promotion_campaign_id IS NOT NULL) AND (promotion_funding_scope = ANY (ARRAY['PLATFORM'::text, 'SELLER'::text])) AND (promotion_product_code IS NOT NULL) AND (promotion_root_catalog_version IS NOT NULL) AND (btrim(promotion_product_code) <> ''::text) AND (btrim(promotion_root_catalog_version) <> ''::text) AND (promotion_root_catalog_version = pricing_version)))),
    CONSTRAINT chk_dealer_lot_promotion_scope CHECK ((((promotion_campaign_id IS NULL) AND (promotion_funding_scope IS NULL)) OR ((promotion_campaign_id IS NOT NULL) AND (promotion_funding_scope = ANY (ARRAY['PLATFORM'::text, 'SELLER'::text]))))),
    CONSTRAINT chk_dealer_lot_promotion_snapshot CHECK ((jsonb_typeof(promotion_snapshot_jsonb) = 'object'::text)),
    CONSTRAINT chk_dealer_lot_source_kind CHECK ((source_kind = ANY (ARRAY['manufacturer_origin'::text, 'platform_purchase'::text, 'direct_resale'::text, 'opening_balance'::text]))),
    CONSTRAINT chk_dealer_lot_standard_reference CHECK (((standard_reference_cents IS NULL) OR (standard_reference_cents > 0))),
    CONSTRAINT chk_dealer_lot_status CHECK ((status = ANY (ARRAY['active'::text, 'consumed'::text, 'refund_pending'::text, 'reversed'::text])))
);


