    CONSTRAINT chk_dealer_fulfillment_hop_money CHECK (((seller_cost_basis_cents > 0) AND (sale_amount_cents > 0) AND (margin_cents >= 0) AND (sale_amount_cents = (seller_cost_basis_cents + margin_cents)))),
    CONSTRAINT chk_dealer_fulfillment_hop_parties CHECK ((seller_user_id <> buyer_user_id)),
