    CONSTRAINT chk_dealer_fulfillment_hop_promotion CHECK ((((promotion_discount_bps >= 1) AND (promotion_discount_bps <= 10000)) AND (((promotion_campaign_id IS NULL) AND (promotion_funding_scope IS NULL) AND (promotion_sponsor_user_id IS NULL) AND (promotion_discount_bps = 10000)) OR ((promotion_campaign_id IS NOT NULL) AND (promotion_funding_scope = ANY (ARRAY['PLATFORM'::text, 'SELLER'::text])))) AND (jsonb_typeof(promotion_snapshot_jsonb) = 'object'::text))),
    CONSTRAINT chk_dealer_fulfillment_hop_source CHECK ((source_kind = ANY (ARRAY['platform_root'::text, 'dealer_resale'::text]))),
