    CONSTRAINT chk_dealer_fulfillment_hop_values CHECK (((hop_seq >= 0) AND (points > 0) AND (existing_inventory_points >= 0) AND (jit_shortfall_points >= 0) AND (mint_points >= 0) AND (((existing_inventory_points + jit_shortfall_points) + mint_points) = points) AND (standard_reference_cents > 0)))
);


