    updated_by integer,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT chk_dealer_resale_policy_bounds CHECK (((authorized_min_markup_bps >= 10000) AND (authorized_max_markup_bps >= authorized_min_markup_bps) AND ((downstream_markup_bps >= authorized_min_markup_bps) AND (downstream_markup_bps <= authorized_max_markup_bps)))),
    CONSTRAINT chk_dealer_resale_policy_markup CHECK ((downstream_markup_bps >= 10000)),
    CONSTRAINT chk_dealer_resale_policy_row_version CHECK ((row_version >= 1)),
    CONSTRAINT chk_dealer_resale_policy_version CHECK ((btrim(policy_version) <> ''::text))
);


