    reversed_at timestamp with time zone,
    revenue_ledger_id bigint,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT chk_dealer_profit_cost_positive CHECK ((seller_cost_basis_cents > 0)),
    CONSTRAINT chk_dealer_profit_money CHECK (((seller_cost_basis_cents >= 0) AND (sale_amount_cents >= 0) AND (margin_cents >= 0) AND (sale_amount_cents = (seller_cost_basis_cents + margin_cents)))),
    CONSTRAINT chk_dealer_profit_parties CHECK ((seller_user_id <> buyer_user_id)),
    CONSTRAINT chk_dealer_profit_status CHECK ((status = ANY (ARRAY['pending'::text, 'available'::text, 'reversed'::text])))
);


