    CONSTRAINT chk_dealer_resale_promo_scope CHECK ((((funding_scope = 'PLATFORM'::text) AND (sponsor_user_id IS NULL) AND (seller_user_id IS NULL)) OR ((funding_scope = 'SELLER'::text) AND (seller_user_id IS NOT NULL) AND (sponsor_user_id = seller_user_id)))),
