--
-- Name: marketing_v_brands_health; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.marketing_v_brands_health AS
 SELECT
        CASE
            WHEN (diagnosis_count = 0) THEN 'new_no_diagnosis'::text
            WHEN (diagnosis_count = 1) THEN 'diagnosed_once'::text
            ELSE 'active_multi_diagnosis'::text
        END AS lifecycle_stage,
    count(*) AS brand_count,
    count(*) FILTER (WHERE (updated_at < (now() - '30 days'::interval))) AS idle_30d,
    round(avg(latest_score), 1) AS avg_latest_score
   FROM public.brands
  WHERE ((COALESCE(is_test, false) = false) AND (deleted_at IS NULL))
  GROUP BY
        CASE
            WHEN (diagnosis_count = 0) THEN 'new_no_diagnosis'::text
            WHEN (diagnosis_count = 1) THEN 'diagnosed_once'::text
            ELSE 'active_multi_diagnosis'::text
        END;


--
-- Name: marketing_v_effect; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.marketing_v_effect AS
 SELECT check_date,
    quote_id,
    count(*) AS keywords_checked,
    count(*) FILTER (WHERE is_compliant) AS keywords_compliant,
    round(avg(detection_rate), 1) AS avg_detection_rate,
    round(avg(effective_rate), 1) AS avg_effective_rate,
    round(((100.0 * (count(*) FILTER (WHERE is_compliant))::numeric) / (NULLIF(count(*), 0))::numeric), 2) AS compliant_rate_pct
   FROM public.keyword_compliance_log
  GROUP BY check_date, quote_id;


