    amount bigint NOT NULL,
    balance_after bigint NOT NULL,
    feature_code text,
    description text,
    order_id text,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    brand_id integer,
    source character varying(40),
    consumption_version text
);


--
-- Name: marketing_v_feature_usage; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.marketing_v_feature_usage AS
 SELECT pt.feature_code,
    fp.feature_name,
    count(*) AS usage_count,
    count(DISTINCT pt.user_id) AS distinct_users,
    (sum(abs(pt.amount)))::bigint AS points_spent
   FROM (public.point_transactions pt
     LEFT JOIN public.feature_pricing fp ON ((fp.feature_code = pt.feature_code)))
  WHERE ((pt.type = 'consume'::text) AND (pt.feature_code IS NOT NULL))
  GROUP BY pt.feature_code, fp.feature_name;


