    CONSTRAINT chk_recharge_actual_payment_channel CHECK (((actual_payment_channel IS NULL) OR (actual_payment_channel = ANY (ARRAY['wechat_jsapi'::text, 'wechat_native'::text, 'xunhupay'::text, 'manual_bank'::text, 'unknown'::text])))),
    CONSTRAINT chk_recharge_pricing_snapshot_object CHECK (((pricing_snapshot_jsonb IS NULL) OR (jsonb_typeof(pricing_snapshot_jsonb) = 'object'::text))),
    CONSTRAINT chk_recharge_quote_anchor_complete CHECK (((price_quote_id IS NULL) OR ((pricing_catalog_version IS NOT NULL) AND (pricing_snapshot_jsonb IS NOT NULL))))
);


