);


--
-- Name: marketing_v_funnel; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.marketing_v_funnel AS
 WITH reg AS (
         SELECT count(*) AS c
           FROM public.users
        ), act AS (
         SELECT count(DISTINCT brands.owner_user_id) AS c
           FROM public.brands
          WHERE ((brands.diagnosis_count > 0) AND (brands.owner_user_id IS NOT NULL))
        ), spend AS (
         SELECT count(DISTINCT point_transactions.user_id) AS c
           FROM public.point_transactions
          WHERE (point_transactions.type = 'consume'::text)
        ), charge AS (
         SELECT count(DISTINCT recharge_orders.user_id) AS c
           FROM public.recharge_orders
          WHERE (recharge_orders.payment_status = 'paid'::text)
        ), repur AS (
         SELECT count(*) AS c
           FROM ( SELECT recharge_orders.user_id
                   FROM public.recharge_orders
                  WHERE (recharge_orders.payment_status = 'paid'::text)
                  GROUP BY recharge_orders.user_id
                 HAVING (count(*) >= 2)) t
        )
 SELECT reg.c AS registered,
    act.c AS activated,
    spend.c AS first_spend,
    charge.c AS first_charge,
    repur.c AS repurchase,
    round(((100.0 * (act.c)::numeric) / (NULLIF(reg.c, 0))::numeric), 2) AS activated_rate_pct,
    round(((100.0 * (spend.c)::numeric) / (NULLIF(act.c, 0))::numeric), 2) AS spend_rate_pct,
    round(((100.0 * (charge.c)::numeric) / (NULLIF(reg.c, 0))::numeric), 2) AS charge_rate_pct,
    round(((100.0 * (repur.c)::numeric) / (NULLIF(charge.c, 0))::numeric), 2) AS repurchase_rate_pct
   FROM reg,
    act,
    spend,
    charge,
    repur;


