CREATE VIEW public.marketing_v_levers AS
 SELECT id AS sku_template_id,
    template_code,
    sku_type,
    default_name,
    default_subtitle,
    points_granted,
    suggested_retail_cents,
    round(((suggested_retail_cents)::numeric / 100.0), 2) AS suggested_retail_yuan,
    is_active,
    created_at
   FROM public.sku_templates st
  WHERE (is_active = true);


--
-- Name: marketing_v_pending_orders; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.marketing_v_pending_orders AS
 SELECT ro.id AS order_id,
    ro.user_id,
    u.username,
        CASE
            WHEN ((u.phone IS NOT NULL) AND (length(u.phone) >= 11)) THEN (("left"(u.phone, 3) || '****'::text) || "right"(u.phone, 4))
            ELSE NULL::text
        END AS phone_masked,
    ro.amount_cents,
    round(((ro.amount_cents)::numeric / 100.0), 2) AS amount_yuan,
    ro.payment_method,
    ro.payment_status,
    ro.settlement_mode,
    ro.agent_user_id,
    ro.created_at,
    (EXTRACT(epoch FROM (now() - (ro.created_at)::timestamp with time zone)))::bigint AS age_seconds
   FROM (public.recharge_orders ro
     LEFT JOIN public.users u ON ((u.id = ro.user_id)))
  WHERE (ro.payment_status = 'pending'::text);


--
-- Name: marketing_v_recharge_pulse; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.marketing_v_recharge_pulse AS
 SELECT ( SELECT (count(*))::integer AS count
           FROM public.recharge_orders
          WHERE ((recharge_orders.payment_status = 'paid'::text) AND (recharge_orders.paid_at > (now() - '7 days'::interval)))) AS paid_recharges_7d,
    ( SELECT (EXTRACT(epoch FROM (now() - (max(recharge_orders.paid_at))::timestamp with time zone)))::bigint AS "extract"
           FROM public.recharge_orders
          WHERE (recharge_orders.payment_status = 'paid'::text)) AS last_recharge_age_seconds;


--
-- Name: marketing_v_register_no_diagnosis; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.marketing_v_register_no_diagnosis AS
 SELECT id AS user_id,
    username,
    created_at,
    (EXTRACT(epoch FROM (now() - (created_at)::timestamp with time zone)) / (86400)::numeric) AS age_days
   FROM public.users u
  WHERE ((created_at < (now() - '7 days'::interval)) AND (NOT (EXISTS ( SELECT 1
           FROM public.brands b
          WHERE ((b.owner_user_id = u.id) AND (b.diagnosis_count > 0))))));


--
-- Name: marketing_v_self_ledger; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.marketing_v_self_ledger AS
 SELECT ( SELECT count(*) AS count
           FROM public.marketing_cases) AS cases_total,
    ( SELECT count(*) AS count
           FROM public.marketing_cases
          WHERE (marketing_cases.status = 'pending'::text)) AS cases_pending,
    ( SELECT count(*) AS count
           FROM public.marketing_cases
          WHERE (marketing_cases.status = 'approved'::text)) AS cases_approved,
    ( SELECT count(*) AS count
           FROM public.marketing_cases
          WHERE (marketing_cases.status = 'executed'::text)) AS cases_executed,
    ( SELECT count(*) AS count
           FROM public.marketing_cases
          WHERE (marketing_cases.status = 'rejected'::text)) AS cases_rejected,
    ( SELECT COALESCE(sum(marketing_grants.points), (0)::numeric) AS "coalesce"
           FROM public.marketing_grants
          WHERE (marketing_grants.status = 'applied'::text)) AS grants_applied_points,
    ( SELECT count(*) AS count
           FROM public.marketing_touch_events
          WHERE (marketing_touch_events.status = 'sent'::text)) AS touches_sent,
    ( SELECT count(*) AS count
           FROM public.marketing_measurements
          WHERE marketing_measurements.converted) AS measured_conversions;


