CREATE TABLE public.user_wallets (
    user_id integer NOT NULL,
    paid_points bigint DEFAULT 0 NOT NULL,
    bonus_points bigint DEFAULT 0 NOT NULL,
    total_recharged bigint DEFAULT 0 NOT NULL,
    agent_level integer DEFAULT 0 NOT NULL,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    frozen_points bigint DEFAULT 0 NOT NULL,
    commission_points bigint DEFAULT 0 NOT NULL,
    deduction_preference character varying(20) DEFAULT 'default'::character varying NOT NULL,
    agent_verified boolean DEFAULT false,
    withdrawal_kyc_verified boolean DEFAULT false,
    withdrawal_kyc_real_name text,
    auto_monitor_after_publish boolean DEFAULT false NOT NULL,
    is_kyc_passed boolean DEFAULT false,
    bank_account_verified boolean DEFAULT false,
    agent_tier character varying(20) DEFAULT 'standard'::character varying,
    charge_notify_level character varying(20) DEFAULT NULL::character varying,
    CONSTRAINT check_bonus_non_negative CHECK ((bonus_points >= 0)),
    CONSTRAINT check_commission_non_negative CHECK ((commission_points >= 0)),
    CONSTRAINT check_frozen_non_negative CHECK ((frozen_points >= 0)),
    CONSTRAINT check_paid_non_negative CHECK ((paid_points >= 0))
);


--
-- Name: marketing_v_wallet_dist; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.marketing_v_wallet_dist AS
 SELECT
        CASE
            WHEN ((paid_points + bonus_points) = 0) THEN '0'::text
            WHEN ((paid_points + bonus_points) < 1000) THEN '1-999'::text
            WHEN ((paid_points + bonus_points) < 5000) THEN '1000-4999'::text
            WHEN ((paid_points + bonus_points) < 20000) THEN '5000-19999'::text
            ELSE '20000+'::text
        END AS balance_bucket,
    count(*) AS wallet_count,
    (sum(paid_points))::bigint AS sum_paid_points,
    (sum(bonus_points))::bigint AS sum_bonus_points,
    count(*) FILTER (WHERE ((total_recharged = 0) AND ((paid_points + bonus_points) = 0))) AS exhausted_trial_cohort
   FROM public.user_wallets
  GROUP BY
        CASE
            WHEN ((paid_points + bonus_points) = 0) THEN '0'::text
            WHEN ((paid_points + bonus_points) < 1000) THEN '1-999'::text
            WHEN ((paid_points + bonus_points) < 5000) THEN '1000-4999'::text
            WHEN ((paid_points + bonus_points) < 20000) THEN '5000-19999'::text
            ELSE '20000+'::text
        END;


