--

CREATE TABLE public.monitoring_results (
    id integer NOT NULL,
    task_id integer,
    keyword_id integer,
    confirmed_keyword_id integer,
    keyword text NOT NULL,
    platform text NOT NULL,
    round_number integer DEFAULT 1,
    is_detected smallint DEFAULT 0,
    mention_type text DEFAULT 'none'::text,
    response_snippet text,
    full_response text,
    tested_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    response_char_count integer DEFAULT 0,
    search_citations text,
    competitors_mentioned jsonb DEFAULT '[]'::jsonb,
    sent_question_snapshot text,
    keyword_source character varying(32) DEFAULT 'legacy_unknown'::character varying,
    keyword_type character varying(32) DEFAULT 'legacy_unknown'::character varying,
    question_family character varying(64) DEFAULT 'legacy_unknown'::character varying,
    question_family_version character varying(80) DEFAULT 'legacy_unknown'::character varying,
    keyword_source_id bigint,
    keyword_resolver_status character varying(32) DEFAULT 'legacy_unknown'::character varying,
    provider character varying(64) DEFAULT 'legacy_unknown'::character varying,
    model character varying(128) DEFAULT 'legacy_unknown'::character varying,
    model_revision character varying(128) DEFAULT 'legacy_unknown'::character varying,
    model_revision_unknown_reason character varying(64),
    surface character varying(64) DEFAULT 'legacy_unknown'::character varying,
    search_mode character varying(64) DEFAULT 'legacy_unknown'::character varying,
    response_status character varying(32) DEFAULT 'legacy_unknown'::character varying,
    target_brand_snapshot text,
    target_entity_snapshot text,
    target_outcome character varying(40) DEFAULT 'legacy_unknown'::character varying,
    outcome_resolver_version character varying(80) DEFAULT 'legacy_unknown'::character varying,
    outcome_resolver_confidence numeric(5,4),
    lineage_version character varying(80) DEFAULT 'legacy_unknown'::character varying,
    lineage_status character varying(32) DEFAULT 'legacy_unknown'::character varying,
    lineage_error_reason text,
    provider_request_id text,
    sent_at timestamp with time zone,
    identity_review_state character varying(24) DEFAULT 'not_required'::character varying NOT NULL,
    identity_brand_id integer,
    identity_candidates jsonb DEFAULT '[]'::jsonb NOT NULL,
    identity_evidence_snippet text,
    identity_evidence_hash character(64),
    identity_decision_version bigint DEFAULT 0 NOT NULL,
    identity_resolved_at timestamp with time zone,
    identity_resolved_by bigint,
    CONSTRAINT chk_monitoring_results_identity_candidates CHECK ((jsonb_typeof(identity_candidates) = 'array'::text)),
    CONSTRAINT chk_monitoring_results_identity_markers CHECK ((((identity_review_state)::text = 'pending'::text) = (((response_status)::text = 'brand_identity_unresolved'::text) OR (mention_type = 'pending_identity'::text)))),
    CONSTRAINT chk_monitoring_results_identity_pending CHECK ((((identity_review_state)::text <> 'pending'::text) OR (((response_status)::text = 'brand_identity_unresolved'::text) AND (mention_type = 'pending_identity'::text) AND (identity_brand_id IS NOT NULL) AND (identity_evidence_hash IS NOT NULL) AND (identity_decision_version = 0)))),
    CONSTRAINT chk_monitoring_results_identity_review_state CHECK (((identity_review_state)::text = ANY ((ARRAY['not_required'::character varying, 'pending'::character varying, 'confirmed'::character varying, 'rejected'::character varying])::text[]))),
    CONSTRAINT chk_monitoring_results_identity_version CHECK ((identity_decision_version >= 0))
);


