--
-- Name: monitoring_run_cells; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.monitoring_run_cells (
    id bigint NOT NULL,
    task_id integer NOT NULL,
    brand_id integer NOT NULL,
    keyword_id bigint NOT NULL,
    keyword_source character varying(16) NOT NULL,
    quote_id integer,
    keyword_snapshot text NOT NULL,
    question_snapshot text NOT NULL,
    target_brand_snapshot text NOT NULL,
    platform character varying(32) NOT NULL,
    is_planned boolean NOT NULL,
    state character varying(40) DEFAULT 'queued'::character varying NOT NULL,
    entitlement_snapshot jsonb NOT NULL,
    order_snapshot jsonb NOT NULL,
    fulfillment_credential uuid NOT NULL,
    fulfillment_state character varying(24) DEFAULT 'reserved'::character varying NOT NULL,
    settlement_reference character varying(160),
    plan_hash character(64) NOT NULL,
    attempt_count integer DEFAULT 0 NOT NULL,
    retry_count integer DEFAULT 0 NOT NULL,
    claim_token uuid,
    claim_until timestamp with time zone,
    provider_dispatched_at timestamp with time zone,
    provider_request_id text,
    result_id integer,
    error_code character varying(80),
    error_message text,
    started_at timestamp with time zone,
    completed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT chk_monitoring_run_cells_claim CHECK (((((state)::text = 'running'::text) AND (claim_token IS NOT NULL) AND (claim_until IS NOT NULL)) OR (((state)::text <> 'running'::text) AND (claim_token IS NULL) AND (claim_until IS NULL)))),
    CONSTRAINT chk_monitoring_run_cells_counts CHECK (((attempt_count >= 0) AND (retry_count >= 0) AND (retry_count <= attempt_count))),
    CONSTRAINT chk_monitoring_run_cells_fulfillment_state CHECK (((fulfillment_state)::text = ANY ((ARRAY['reserved'::character varying, 'covered'::character varying, 'admin_covered'::character varying, 'coverage_unknown'::character varying, 'released'::character varying])::text[]))),
    CONSTRAINT chk_monitoring_run_cells_json CHECK (((jsonb_typeof(entitlement_snapshot) = 'object'::text) AND (jsonb_typeof(order_snapshot) = 'object'::text))),
    CONSTRAINT chk_monitoring_run_cells_keyword_source CHECK (((keyword_source)::text = ANY ((ARRAY['confirmed'::character varying, 'contract'::character varying, 'extra'::character varying])::text[]))),
    CONSTRAINT chk_monitoring_run_cells_plan_shape CHECK ((is_planned OR ((NOT is_planned) AND ((state)::text = 'unavailable'::text)))),
    CONSTRAINT chk_monitoring_run_cells_platform CHECK (((platform)::text = ANY ((ARRAY['dashscope'::character varying, 'deepseek'::character varying, 'kimi'::character varying, 'doubao'::character varying])::text[]))),
    CONSTRAINT chk_monitoring_run_cells_result_terminal CHECK (((((state)::text = ANY ((ARRAY['succeeded'::character varying, 'pending_identity'::character varying])::text[])) AND (result_id IS NOT NULL)) OR (((state)::text <> ALL ((ARRAY['succeeded'::character varying, 'pending_identity'::character varying])::text[])) AND (result_id IS NULL)))),
    CONSTRAINT chk_monitoring_run_cells_state CHECK (((state)::text = ANY ((ARRAY['queued'::character varying, 'running'::character varying, 'succeeded'::character varying, 'failed'::character varying, 'pending_identity'::character varying, 'unavailable'::character varying, 'pending_provider_confirmation'::character varying])::text[])))
);


