    CONSTRAINT org_monitoring_tasks_shape CHECK (((organization_id IS NULL) OR ((created_by_actor_kind = ANY (ARRAY['owner'::text, 'member'::text, 'system'::text])) AND (created_by_user_id IS NOT NULL) AND (responsible_user_id IS NOT NULL) AND (artifact_visibility = ANY (ARRAY['private'::text, 'team'::text, 'external'::text])) AND ((created_by_actor_kind <> 'member'::text) OR (created_by_membership_id IS NOT NULL)))))
);


