    CONSTRAINT organization_approval_policies_policy_hash_check CHECK ((length(policy_hash) = 64)),
    CONSTRAINT organization_approval_policies_status_check CHECK ((status = ANY (ARRAY['active'::text, 'superseded'::text, 'revoked'::text]))),
    CONSTRAINT organization_approval_policies_threshold_points_check CHECK (((threshold_points IS NULL) OR (threshold_points >= 0))),
    CONSTRAINT organization_approval_policies_version_check CHECK ((version >= 1)),
    CONSTRAINT organization_approval_policy_amount_valid CHECK (((min_points IS NULL) OR (max_points IS NULL) OR (max_points >= min_points))),
    CONSTRAINT organization_approval_policy_subject_valid CHECK (((membership_id IS NULL) OR (role_id IS NULL))),
    CONSTRAINT organization_approval_policy_window_valid CHECK (((effective_to IS NULL) OR (effective_to > effective_from)))
);


