    CONSTRAINT organization_charge_payer_split_valid CHECK (((within_limit_points >= 0) AND (overage_points >= 0) AND ((within_limit_points + overage_points) <= reserved_ceiling_points))),
    CONSTRAINT organization_charge_refund_valid CHECK (((actual_points IS NULL) OR (refunded_points <= actual_points)))
);


