--

CREATE TABLE public.price_quotes (
    quote_id text NOT NULL,
    quote_type text NOT NULL,
    currency text DEFAULT 'CNY'::text NOT NULL,
    catalog_version text NOT NULL,
    catalog_version_id bigint,
    channel_relationship_version text,
    seller_policy_version text,
    product_code text NOT NULL,
    quantity integer DEFAULT 1 NOT NULL,
    seller_legal_entity_id text DEFAULT 'PLATFORM'::text NOT NULL,
    buyer_user_id integer NOT NULL,
    channel_account_code text,
    channel_beneficiary_user_id integer,
    payment_collector text DEFAULT 'PLATFORM'::text NOT NULL,
    points_granted bigint NOT NULL,
    bonus_points bigint DEFAULT 0 NOT NULL,
    base_price_cents integer NOT NULL,
    effective_multiplier_bps integer,
    final_price_cents integer NOT NULL,
    upstream_cost_basis_cents integer,
    expires_at timestamp with time zone NOT NULL,
    calculation_hash text NOT NULL,
    status text DEFAULT 'issued'::text NOT NULL,
    used_order_id text,
    idempotency_key text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    consumed_at timestamp with time zone,
    pricing_snapshot_jsonb jsonb,
    CONSTRAINT chk_price_quote_money_nonnegative CHECK (((base_price_cents >= 0) AND (final_price_cents >= 0) AND ((effective_multiplier_bps IS NULL) OR (effective_multiplier_bps > 0)) AND ((upstream_cost_basis_cents IS NULL) OR (upstream_cost_basis_cents >= 0)))),
    CONSTRAINT chk_price_quote_snapshot_catalog_id CHECK (((pricing_snapshot_jsonb IS NULL) OR (catalog_version_id IS NOT NULL))),
    CONSTRAINT chk_price_quote_snapshot_object CHECK (((pricing_snapshot_jsonb IS NULL) OR (jsonb_typeof(pricing_snapshot_jsonb) = 'object'::text))),
    CONSTRAINT chk_price_quote_status_fields_consistent CHECK ((((status = 'consumed'::text) AND (used_order_id IS NOT NULL) AND (consumed_at IS NOT NULL)) OR ((status <> 'consumed'::text) AND (used_order_id IS NULL) AND (consumed_at IS NULL)))),
    CONSTRAINT price_quotes_bonus_points_check CHECK ((bonus_points >= 0)),
    CONSTRAINT price_quotes_currency_check CHECK ((currency = 'CNY'::text)),
    CONSTRAINT price_quotes_final_price_cents_check CHECK ((final_price_cents >= 0)),
    CONSTRAINT price_quotes_points_granted_check CHECK ((points_granted >= 0)),
    CONSTRAINT price_quotes_quantity_check CHECK ((quantity >= 1)),
    CONSTRAINT price_quotes_quote_type_check CHECK ((quote_type = ANY (ARRAY['procurement'::text, 'retail'::text]))),
    CONSTRAINT price_quotes_status_check CHECK ((status = ANY (ARRAY['issued'::text, 'consumed'::text, 'expired'::text, 'cancelled'::text])))
);


