);


--
-- Name: purchase_agreement_acceptances; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.purchase_agreement_acceptances (
    acceptance_id text NOT NULL,
    user_id integer NOT NULL,
    agreement_type text NOT NULL,
    agreement_version text NOT NULL,
    content_hash text NOT NULL,
    accepted_at timestamp with time zone DEFAULT now() NOT NULL,
    ip_address text,
    user_agent text,
    surface text NOT NULL,
    evidence_jsonb jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT chk_purchase_acceptance_evidence CHECK ((jsonb_typeof(evidence_jsonb) = 'object'::text)),
    CONSTRAINT chk_purchase_acceptance_nonblank CHECK (((btrim(acceptance_id) <> ''::text) AND (btrim(agreement_type) <> ''::text) AND (btrim(agreement_version) <> ''::text) AND (btrim(content_hash) <> ''::text) AND (btrim(surface) <> ''::text)))
);


--
-- Name: quote_pricing_snapshots; Type: TABLE; Schema: public; Owner: -
