    brand_id integer NOT NULL,
    selection_session_id integer NOT NULL,
    version integer NOT NULL,
    actor_user_id integer,
    actor_membership_id bigint,
    previous_coefficient numeric(8,4),
    coefficient numeric(8,4),
    reason text NOT NULL,
    calculation_version text NOT NULL,
    pricing_snapshot jsonb NOT NULL,
    clusters_snapshot jsonb,
    snapshot_hash character(64) NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT quote_pricing_snapshots_calculation_version_check CHECK ((btrim(calculation_version) <> ''::text)),
    CONSTRAINT quote_pricing_snapshots_clusters_snapshot_check CHECK (((clusters_snapshot IS NULL) OR (jsonb_typeof(clusters_snapshot) = 'object'::text))),
    CONSTRAINT quote_pricing_snapshots_pricing_snapshot_check CHECK ((jsonb_typeof(pricing_snapshot) = 'object'::text)),
    CONSTRAINT quote_pricing_snapshots_reason_check CHECK ((btrim(reason) <> ''::text)),
    CONSTRAINT quote_pricing_snapshots_snapshot_hash_check CHECK ((snapshot_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT quote_pricing_snapshots_version_check CHECK ((version > 0))
);


