CREATE TABLE public.service_refund_cash_jobs (
    cash_job_id text NOT NULL,
    case_id text NOT NULL,
    source_order_id text NOT NULL,
    consumer_user_id integer NOT NULL,
    responsible_service_user_id integer NOT NULL,
    amount_cents bigint NOT NULL,
    original_payment_route text NOT NULL,
    status text DEFAULT 'queued'::text NOT NULL,
    attempt_count integer DEFAULT 0 NOT NULL,
    idempotency_key text NOT NULL,
    provider_refund_id text,
    provider_evidence_jsonb jsonb DEFAULT '{}'::jsonb NOT NULL,
    last_error text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    completed_at timestamp with time zone,
    CONSTRAINT chk_service_refund_cash_amount CHECK (((amount_cents > 0) AND (attempt_count >= 0))),
    CONSTRAINT chk_service_refund_cash_evidence CHECK ((jsonb_typeof(provider_evidence_jsonb) = 'object'::text)),
    CONSTRAINT chk_service_refund_cash_route CHECK ((btrim(original_payment_route) <> ''::text)),
    CONSTRAINT chk_service_refund_cash_status CHECK ((status = ANY (ARRAY['queued'::text, 'provider_processing'::text, 'completed'::text, 'failed'::text, 'manual_review'::text])))
);


