    status text DEFAULT 'open'::text NOT NULL,
    resolution_jsonb jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    resolved_at timestamp with time zone,
    CONSTRAINT chk_service_refund_funding_resolution CHECK ((jsonb_typeof(resolution_jsonb) = 'object'::text)),
    CONSTRAINT chk_service_refund_funding_shortage CHECK ((shortage_cents > 0)),
    CONSTRAINT chk_service_refund_funding_status CHECK ((status = ANY (ARRAY['open'::text, 'recovering'::text, 'manual_review'::text, 'closed'::text])))
);


--
-- Name: service_refund_liability_ledger; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.service_refund_liability_ledger (
    liability_id bigint NOT NULL,
    case_id text NOT NULL,
    source_order_id text NOT NULL,
    service_user_id integer NOT NULL,
    refund_amount_cents bigint NOT NULL,
    pending_settlement_offset_cents bigint DEFAULT 0 NOT NULL,
    reserve_offset_cents bigint DEFAULT 0 NOT NULL,
    negative_settlement_cents bigint DEFAULT 0 NOT NULL,
    status text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT chk_service_refund_liability_money CHECK (((refund_amount_cents > 0) AND (pending_settlement_offset_cents >= 0) AND (reserve_offset_cents >= 0) AND (negative_settlement_cents >= 0) AND (refund_amount_cents = ((pending_settlement_offset_cents + reserve_offset_cents) + negative_settlement_cents)))),
    CONSTRAINT chk_service_refund_liability_status CHECK ((status = ANY (ARRAY['covered'::text, 'negative_settlement'::text, 'recovered'::text, 'closed'::text])))
);


