--
-- Name: v_bonus_grant_reconcile; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_bonus_grant_reconcile AS
 SELECT 'agent'::text AS owner_type,
    w.agent_user_id AS owner_id,
    w.bonus_inventory_points AS pool_balance,
    COALESCE(g.active_points, (0)::numeric) AS grant_active_points,
    COALESCE(g.frozen_points, (0)::numeric) AS grant_frozen_points
   FROM (public.agent_inventory_wallets w
     LEFT JOIN ( SELECT bonus_grants.owner_id,
            sum(((bonus_grants.granted_points - bonus_grants.consumed_points) - bonus_grants.frozen_points)) FILTER (WHERE (bonus_grants.status = 'active'::text)) AS active_points,
            sum(bonus_grants.frozen_points) AS frozen_points
           FROM public.bonus_grants
          WHERE (bonus_grants.owner_type = 'agent'::text)
          GROUP BY bonus_grants.owner_id) g ON ((g.owner_id = w.agent_user_id)))
UNION ALL
 SELECT 'customer'::text AS owner_type,
    w.customer_user_id AS owner_id,
    w.bonus_credit_points AS pool_balance,
    COALESCE(g.active_points, (0)::numeric) AS grant_active_points,
    COALESCE(g.frozen_points, (0)::numeric) AS grant_frozen_points
   FROM (public.customer_agent_credit_wallets w
     LEFT JOIN ( SELECT bonus_grants.owner_id,
            sum(((bonus_grants.granted_points - bonus_grants.consumed_points) - bonus_grants.frozen_points)) FILTER (WHERE (bonus_grants.status = 'active'::text)) AS active_points,
            sum(bonus_grants.frozen_points) AS frozen_points
           FROM public.bonus_grants
          WHERE (bonus_grants.owner_type = 'customer'::text)
          GROUP BY bonus_grants.owner_id) g ON ((g.owner_id = w.customer_user_id)));


